    op.execute(
        "CREATE OR REPLACE FUNCTION public.source_snapshot_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE license provider_license_versions; provider market_data_providers; source market_source_series;\nBEGIN\n IF TG_TABLE_NAME='benchmark_snapshots' AND to_jsonb(NEW)->>'snapshot_kind'='composite' THEN RETURN NEW; END IF;\n SELECT * INTO license FROM provider_license_versions WHERE owner_id=NEW.owner_id AND id=NEW.license_version_id AND provider_id=NEW.provider_id;\n SELECT * INTO provider FROM market_data_providers WHERE owner_id=NEW.owner_id AND id=NEW.provider_id;\n IF license.store_permission IS DISTINCT FROM 'allowed' OR license.retention_days IS NULL OR license.effective_at > NEW.first_observed_at OR provider.synthetic IS DISTINCT FROM NEW.synthetic OR provider.adapter_version IS DISTINCT FROM NEW.adapter_version OR NEW.expires_at > NEW.first_observed_at + make_interval(days=>license.retention_days) OR NEW.effective_at > NEW.first_observed_at THEN\n  RAISE EXCEPTION 'Source snapshot policy mismatch' USING ERRCODE='23514';\n END IF;\n IF TG_TABLE_NAME <> 'fx_snapshots' THEN\n  SELECT * INTO source FROM market_source_series WHERE id=NEW.series_id AND owner_id=NEW.owner_id;\n  IF (TG_TABLE_NAME='benchmark_snapshots' AND source.kind IS DISTINCT FROM 'benchmark_level') OR (TG_TABLE_NAME<>'benchmark_snapshots' AND source.kind IS DISTINCT FROM 'security_price') THEN\n   RAISE EXCEPTION 'Snapshot source kind mismatch' USING ERRCODE='23514';\n  END IF;\n END IF;\n RETURN NEW;\nEND $function$\n"
    )
    op.execute(
        "CREATE FUNCTION historical_immutable_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF TG_OP='UPDATE' AND historical_retention_write(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW; END IF;\n IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('historical_policy_versions','historical_evidence_sets','historical_input_snapshots','historical_analytics_runs') AND NOT (to_jsonb(OLD)->>'sealed')::boolean AND (to_jsonb(NEW)->>'sealed')::boolean AND (to_jsonb(OLD)-'sealed')=(to_jsonb(NEW)-'sealed') THEN RETURN NEW; END IF;\n RAISE EXCEPTION 'Immutable historical record' USING ERRCODE='23514';\nEND $$;\nCREATE FUNCTION historical_final_seal() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE sealed boolean;\nBEGIN\n EXECUTE format('SELECT sealed FROM %I WHERE id=$1',TG_TABLE_NAME) INTO sealed USING NEW.id;\n IF sealed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Historical publication is incomplete' USING ERRCODE='23514'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION historical_child_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE parent jsonb; identifier uuid; sealed boolean;\nBEGIN\n identifier:=(to_jsonb(NEW)->>TG_ARGV[1])::uuid;\n IF identifier IS NULL THEN RETURN NEW; END IF;\n EXECUTE format('SELECT to_jsonb(p),pg_xact_status(xmin::text::xid8)=''committed'' FROM %I p WHERE owner_id=$1 AND id=$2',TG_ARGV[0]) INTO parent,sealed USING NEW.owner_id,identifier;\n IF parent IS NULL OR sealed OR (parent->>'sealed')::boolean THEN RAISE EXCEPTION 'Historical parent is sealed' USING ERRCODE='23514'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION historical_scope_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE body jsonb:=to_jsonb(NEW); account uuid; actual uuid; parent_account uuid; relation text; field text; dep historical_dependencies; run historical_analytics_runs; okay boolean; snapshot uuid;\nBEGIN\n account:=(body->>'broker_account_id')::uuid;\n IF body->>'input_id' IS NOT NULL THEN SELECT broker_account_id INTO parent_account FROM historical_input_snapshots WHERE owner_id=NEW.owner_id AND id=(body->>'input_id')::uuid; END IF;\n IF body->>'evidence_id' IS NOT NULL THEN SELECT broker_account_id INTO parent_account FROM historical_evidence_sets WHERE owner_id=NEW.owner_id AND id=(body->>'evidence_id')::uuid; END IF;\n IF body->>'policy_id' IS NOT NULL THEN SELECT broker_account_id INTO parent_account FROM historical_policy_versions WHERE owner_id=NEW.owner_id AND id=(body->>'policy_id')::uuid; END IF;\n IF account IS NOT NULL AND parent_account IS NOT NULL AND account<>parent_account THEN RAISE EXCEPTION 'Historical account mismatch' USING ERRCODE='23514'; END IF;\n account:=COALESCE(account,parent_account);\n IF account IS NOT NULL THEN\n  SELECT c.owner_id INTO actual FROM broker_accounts a JOIN broker_connections c ON c.id=a.connection_id WHERE a.id=account;\n  IF actual IS DISTINCT FROM NEW.owner_id THEN RAISE EXCEPTION 'Historical owner mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n IF TG_TABLE_NAME IN ('historical_dependencies','historical_event_revisions','historical_activity_coverage') THEN\n  FOREACH field IN ARRAY ARRAY['ingestion_run_id','source_record_id','portfolio_snapshot_id','calculation_run_id','reconciliation_run_id','registered_evidence_id'] LOOP\n   IF body->>field IS NOT NULL THEN\n    relation:=CASE field WHEN 'ingestion_run_id' THEN 'ingestion_runs' WHEN 'source_record_id' THEN 'source_records' WHEN 'portfolio_snapshot_id' THEN 'portfolio_snapshots' WHEN 'calculation_run_id' THEN 'calculation_runs' WHEN 'reconciliation_run_id' THEN 'reconciliation_runs' ELSE 'historical_evidence_sets' END;\n    EXECUTE format('SELECT broker_account_id FROM %I WHERE id=$1',relation) INTO actual USING (body->>field)::uuid;\n    IF actual IS DISTINCT FROM account THEN RAISE EXCEPTION 'Historical source account mismatch' USING ERRCODE='23514'; END IF;\n   END IF;\n  END LOOP;\n  IF body->>'source_occurrence_id' IS NOT NULL THEN\n   SELECT r.broker_account_id INTO actual FROM source_record_occurrences o JOIN source_records r ON r.id=o.source_record_id JOIN ingestion_runs i ON i.id=o.ingestion_run_id WHERE o.id=(body->>'source_occurrence_id')::uuid AND i.broker_account_id=r.broker_account_id AND ((body->>'source_record_id') IS NULL OR r.id=(body->>'source_record_id')::uuid);\n   IF actual IS DISTINCT FROM account THEN RAISE EXCEPTION 'Historical occurrence identity mismatch' USING ERRCODE='23514'; END IF;\n  END IF;\n  IF TG_TABLE_NAME='historical_dependencies' AND body->>'registered_evidence_id' IS NOT NULL AND body->>'evidence_id' IS NOT NULL THEN RAISE EXCEPTION 'Nested historical evidence is unsupported' USING ERRCODE='23514'; END IF;\n END IF;\n IF TG_TABLE_NAME='historical_analytics_runs' THEN\n  SELECT broker_account_id INTO actual FROM analytics_runs WHERE owner_id=NEW.owner_id AND id=NEW.analytics_run_id;\n  IF actual IS DISTINCT FROM account THEN RAISE EXCEPTION 'Historical result account mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n IF body->>'listing_id' IS NOT NULL AND body->>'instrument_id' IS NOT NULL THEN\n  SELECT instrument_id INTO actual FROM listings WHERE id=(body->>'listing_id')::uuid;\n  IF actual IS DISTINCT FROM (body->>'instrument_id')::uuid THEN RAISE EXCEPTION 'Historical listing identity mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n IF TG_TABLE_NAME='historical_selected_source_uses' AND body->>'dependency_id' IS NOT NULL THEN\n  SELECT * INTO run FROM historical_analytics_runs WHERE owner_id=NEW.owner_id AND id=NEW.run_id;\n  SELECT * INTO dep FROM historical_dependencies WHERE owner_id=NEW.owner_id AND id=NEW.dependency_id;\n  IF dep.input_id IS DISTINCT FROM run.input_id THEN RAISE EXCEPTION 'Historical use capture mismatch' USING ERRCODE='23514'; END IF;\n  IF NEW.kind='observation' THEN\n   relation:=CASE WHEN dep.price_snapshot_id IS NOT NULL THEN 'price_observations' WHEN dep.fx_snapshot_id IS NOT NULL THEN 'fx_observations' WHEN dep.action_snapshot_id IS NOT NULL THEN 'corporate_action_observations' WHEN dep.benchmark_snapshot_id IS NOT NULL THEN 'benchmark_observations' ELSE NULL END;\n   snapshot:=COALESCE(dep.price_snapshot_id,dep.fx_snapshot_id,dep.action_snapshot_id,dep.benchmark_snapshot_id);\n   IF relation IS NULL THEN RAISE EXCEPTION 'Historical observation reference mismatch' USING ERRCODE='23514'; END IF;\n   EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I WHERE owner_id=$1 AND snapshot_id=$2 AND ordinal=$3)',relation) INTO okay USING NEW.owner_id,snapshot,NEW.observation_index;\n   IF NOT okay THEN RAISE EXCEPTION 'Historical observation ordinal mismatch' USING ERRCODE='23514'; END IF;\n  END IF;\n END IF;\n IF TG_TABLE_NAME='historical_conversion_legs' THEN\n  SELECT run_id INTO actual FROM historical_selected_source_uses WHERE owner_id=NEW.owner_id AND id=NEW.source_use_id;\n  IF actual IS DISTINCT FROM NEW.run_id THEN RAISE EXCEPTION 'Historical FX leg parent mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION historical_economic_seal_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE body jsonb:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; identifier uuid; field text; pinned boolean;\nBEGIN\n IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;\n identifier:=(body->>'id')::uuid;\n field:=CASE TG_TABLE_NAME WHEN 'source_records' THEN 'source_record_id' WHEN 'source_record_occurrences' THEN 'source_occurrence_id' WHEN 'portfolio_snapshots' THEN 'portfolio_snapshot_id' WHEN 'calculation_runs' THEN 'calculation_run_id' WHEN 'reconciliation_runs' THEN 'reconciliation_run_id' ELSE 'portfolio_snapshot_id' END;\n IF TG_TABLE_NAME IN ('snapshot_positions','snapshot_cash') THEN identifier:=(body->>'snapshot_id')::uuid; END IF;\n EXECUTE format('SELECT EXISTS(SELECT 1 FROM historical_dependencies WHERE %I=$1)',field) INTO pinned USING identifier;\n IF pinned THEN RAISE EXCEPTION 'Pinned historical source is immutable' USING ERRCODE='23514'; END IF;\n RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND $$;\nCREATE FUNCTION historical_composite_complete() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE present integer; expected integer;\nBEGIN\n IF NEW.snapshot_kind<>'composite' THEN RETURN NEW; END IF;\n SELECT count(*) INTO present FROM historical_composite_benchmarks WHERE owner_id=NEW.owner_id AND snapshot_id=NEW.id;\n IF present<1 THEN RAISE EXCEPTION 'Composite publication is incomplete' USING ERRCODE='23514'; END IF;\n SELECT count(*) INTO expected FROM benchmark_components WHERE owner_id=NEW.owner_id AND version_id=NEW.benchmark_version_id;\n SELECT count(*) INTO present FROM benchmark_snapshot_components c JOIN benchmark_components b ON b.version_id=NEW.benchmark_version_id AND b.source_id=c.source_id AND b.weight=c.weight AND b.owner_id=c.owner_id WHERE c.owner_id=NEW.owner_id AND c.snapshot_id=NEW.id;\n IF present<>expected THEN RAISE EXCEPTION 'Composite component mismatch' USING ERRCODE='23514'; END IF;\n RETURN NEW;\nEND $$;\n"
    )
