def _install_use_identity() -> None:
    op.execute(
        "CREATE TABLE historical_input_instruments (\n\tinput_id UUID NOT NULL, \n\tlisting_id UUID NOT NULL, \n\tinstrument_id UUID NOT NULL, \n\tcurrency VARCHAR(3) NOT NULL, \n\towner_id UUID NOT NULL, \n\tid UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, \n\tCONSTRAINT pk_historical_input_instruments PRIMARY KEY (id), \n\tCONSTRAINT uq_historical_input_instruments_owner_id UNIQUE (owner_id, id), \n\tCONSTRAINT fk_historical_input_instruments_owner_id_historical_inp_9ea8 FOREIGN KEY(owner_id, input_id) REFERENCES historical_input_snapshots (owner_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_historical_input_instruments_input_id UNIQUE (input_id, listing_id), \n\tCONSTRAINT fk_historical_input_instruments_listing_id_listings FOREIGN KEY(listing_id) REFERENCES listings (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_historical_input_instruments_instrument_id_instruments FOREIGN KEY(instrument_id) REFERENCES instruments (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_historical_input_instruments_owner_id_owners FOREIGN KEY(owner_id) REFERENCES owners (id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_historical_input_instruments_currency_currency CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$')\n)"
    )
    op.execute(
        "CREATE TABLE historical_use_candidates (\n\tsource_use_id UUID NOT NULL, \n\tdependency_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tid UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, \n\tCONSTRAINT pk_historical_use_candidates PRIMARY KEY (id), \n\tCONSTRAINT uq_historical_use_candidates_owner_id UNIQUE (owner_id, id), \n\tCONSTRAINT fk_historical_use_candidates_owner_id_historical_select_024e FOREIGN KEY(owner_id, source_use_id) REFERENCES historical_selected_source_uses (owner_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_historical_use_candidates_owner_id_historical_dependencies FOREIGN KEY(owner_id, dependency_id) REFERENCES historical_dependencies (owner_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_historical_use_candidates_source_use_id UNIQUE (source_use_id, dependency_id), \n\tCONSTRAINT fk_historical_use_candidates_owner_id_owners FOREIGN KEY(owner_id) REFERENCES owners (id) ON DELETE RESTRICT\n)"
    )
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN listing_id UUID")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN instrument_id UUID")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN event_revision_id UUID")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN group_key VARCHAR(120)")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN component_source_id UUID")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN expected_series_id UUID")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN expected_base VARCHAR(3)")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN expected_quote VARCHAR(3)")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN calendar_id UUID")
    op.execute("ALTER TABLE historical_selected_source_uses ADD COLUMN expected_session DATE")
