    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT fk_historical_selected_source_uses_owner_id_source_calendars FOREIGN KEY(owner_id, calendar_id) REFERENCES source_calendars (owner_id, id) ON DELETE RESTRICT"
    )
    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT fk_historical_selected_source_uses_event_revision_id_so_1c6a FOREIGN KEY(event_revision_id) REFERENCES source_records (id) ON DELETE RESTRICT"
    )
    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT fk_historical_use_expected_series FOREIGN KEY(owner_id, expected_series_id) REFERENCES market_source_series (owner_id, id) ON DELETE RESTRICT"
    )
    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT fk_historical_selected_source_uses_instrument_id_instruments FOREIGN KEY(instrument_id) REFERENCES instruments (id) ON DELETE RESTRICT"
    )
    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT ck_historical_selected_source_uses_consumer_kind CHECK (consumer_kind IN ('holding','cash','event','group','benchmark','portfolio'))"
    )
    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT fk_historical_selected_source_uses_listing_id_listings FOREIGN KEY(listing_id) REFERENCES listings (id) ON DELETE RESTRICT"
    )
    op.execute(
        "ALTER TABLE historical_selected_source_uses ADD CONSTRAINT fk_historical_selected_source_uses_owner_id_market_sour_5152 FOREIGN KEY(owner_id, component_source_id) REFERENCES market_source_series (owner_id, id) ON DELETE RESTRICT"
    )
    op.execute(
        "CREATE FUNCTION historical_use_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE selected historical_selected_source_uses; run historical_analytics_runs; capture historical_input_snapshots; dep historical_dependencies;\nBEGIN\n IF TG_TABLE_NAME='historical_use_candidates' THEN\n  SELECT * INTO selected FROM historical_selected_source_uses WHERE id=NEW.source_use_id AND owner_id=NEW.owner_id;\n  SELECT * INTO run FROM historical_analytics_runs WHERE id=selected.run_id AND owner_id=NEW.owner_id;\n  SELECT * INTO dep FROM historical_dependencies WHERE id=NEW.dependency_id AND owner_id=NEW.owner_id;\n  IF selected.kind IS DISTINCT FROM 'missing' OR dep.input_id IS DISTINCT FROM run.input_id OR num_nonnulls(dep.price_snapshot_id,dep.fx_snapshot_id,dep.action_snapshot_id,dep.benchmark_snapshot_id)<>1 THEN RAISE EXCEPTION 'Historical candidate scope mismatch' USING ERRCODE='23514'; END IF;\n  RETURN NEW;\n END IF;\n SELECT * INTO run FROM historical_analytics_runs WHERE id=NEW.run_id AND owner_id=NEW.owner_id;\n SELECT * INTO capture FROM historical_input_snapshots WHERE id=run.input_id AND owner_id=NEW.owner_id;\n IF NEW.listing_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM historical_input_instruments WHERE input_id=capture.id AND owner_id=NEW.owner_id AND listing_id=NEW.listing_id AND (NEW.instrument_id IS NULL OR instrument_id=NEW.instrument_id)) THEN RAISE EXCEPTION 'Historical consumer listing mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.event_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM historical_event_revisions WHERE input_id=capture.id AND owner_id=NEW.owner_id AND revision_id=NEW.event_revision_id::text) THEN RAISE EXCEPTION 'Historical consumer event mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.component_source_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM benchmark_components WHERE version_id=capture.benchmark_version_id AND owner_id=NEW.owner_id AND source_id=NEW.component_source_id) THEN RAISE EXCEPTION 'Historical consumer component mismatch' USING ERRCODE='23514'; END IF;\n IF NEW.group_key IS NOT NULL AND NOT EXISTS(SELECT 1 FROM target_nodes WHERE target_version_id=capture.target_version_id AND owner_id=NEW.owner_id AND key=NEW.group_key) THEN RAISE EXCEPTION 'Historical consumer group mismatch' USING ERRCODE='23514'; END IF;\n IF (NEW.consumer_kind='holding' AND NEW.listing_id IS NULL) OR (NEW.consumer_kind='event' AND NEW.event_revision_id IS NULL) OR (NEW.consumer_kind='benchmark' AND NEW.component_source_id IS NULL) OR (NEW.consumer_kind='group' AND NEW.group_key IS NULL) THEN RAISE EXCEPTION 'Historical consumer identity required' USING ERRCODE='23514'; END IF;\n IF NEW.kind='missing' THEN\n  IF NEW.calendar_id IS NULL OR NOT EXISTS(SELECT 1 FROM historical_dependencies WHERE input_id=capture.id AND owner_id=NEW.owner_id AND calendar_id=NEW.calendar_id) OR NEW.reason IS NULL OR NOT ((NEW.expected_series_id IS NOT NULL AND NEW.expected_base IS NULL AND NEW.expected_quote IS NULL) OR (NEW.expected_series_id IS NULL AND NEW.expected_base IS NOT NULL AND NEW.expected_quote IS NOT NULL AND NEW.expected_base<>NEW.expected_quote)) THEN RAISE EXCEPTION 'Historical missing-use identity mismatch' USING ERRCODE='23514'; END IF;\n ELSIF num_nonnulls(NEW.expected_series_id,NEW.expected_base,NEW.expected_quote,NEW.calendar_id,NEW.expected_session,NEW.reason)<>0 THEN RAISE EXCEPTION 'Historical use shape mismatch' USING ERRCODE='23514'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER historical_use_identity BEFORE INSERT ON historical_selected_source_uses FOR EACH ROW EXECUTE FUNCTION historical_use_identity_guard();\nCREATE TRIGGER historical_use_identity BEFORE INSERT ON historical_use_candidates FOR EACH ROW EXECUTE FUNCTION historical_use_identity_guard();\nCREATE TRIGGER historical_scope BEFORE INSERT OR UPDATE ON historical_input_instruments FOR EACH ROW EXECUTE FUNCTION historical_scope_guard();\nCREATE TRIGGER historical_immutable BEFORE UPDATE OR DELETE ON historical_input_instruments FOR EACH ROW EXECUTE FUNCTION historical_immutable_guard();\nCREATE TRIGGER historical_child_0 BEFORE INSERT ON historical_input_instruments FOR EACH ROW EXECUTE FUNCTION historical_child_guard('historical_input_snapshots','input_id');\nCREATE TRIGGER historical_immutable BEFORE UPDATE OR DELETE ON historical_use_candidates FOR EACH ROW EXECUTE FUNCTION historical_immutable_guard();\nCREATE TRIGGER historical_child_0 BEFORE INSERT ON historical_use_candidates FOR EACH ROW EXECUTE FUNCTION historical_child_guard('historical_selected_source_uses','source_use_id');\n"
    )


