def _install_activity_proofs() -> None:
    op.execute("""
        CREATE FUNCTION historical_activity_proof_guard() RETURNS trigger
        LANGUAGE plpgsql AS $$
        DECLARE identifier uuid; receipt timestamptz; observed_end timestamptz;
            run ingestion_runs; evidence historical_evidence_sets;
        BEGIN
            IF TG_TABLE_NAME='historical_activity_coverage' THEN
                SELECT * INTO run FROM ingestion_runs WHERE id=NEW.ingestion_run_id;
                SELECT * INTO evidence FROM historical_evidence_sets
                    WHERE owner_id=NEW.owner_id AND id=NEW.evidence_id;
                IF run.id IS NULL OR evidence.id IS NULL
                    OR run.broker_account_id<>evidence.broker_account_id
                    OR run.status<>'succeeded' OR run.mode<>'full'
                    OR NOT (run.effective_capabilities ? NEW.capability)
                    OR run.completed_at IS NULL
                    OR run.completed_at>NEW.first_observed_at
                    OR NEW.first_observed_at<>evidence.first_observed_at THEN
                    RAISE EXCEPTION 'Historical activity proof mismatch' USING ERRCODE='23514';
                END IF;
                SELECT max(o.source_updated_at) INTO observed_end
                    FROM source_record_occurrences o JOIN source_records s ON s.id=o.source_record_id
                    WHERE o.ingestion_run_id=run.id
                        AND s.broker_account_id=run.broker_account_id
                        AND s.capability IN ('account_summary','portfolio_positions')
                        AND o.observed_at<=NEW.first_observed_at;
                IF observed_end IS NULL OR observed_end<NEW.end_at THEN
                    RAISE EXCEPTION 'Historical activity interval is unsupported' USING ERRCODE='23514';
                END IF;
                RETURN NEW;
            END IF;
            IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
            IF TG_TABLE_NAME='ingestion_runs' THEN identifier:=OLD.id;
            ELSE identifier:=CASE WHEN TG_OP='INSERT' THEN NEW.ingestion_run_id
                ELSE OLD.ingestion_run_id END; END IF;
            IF EXISTS(SELECT 1 FROM historical_dependencies WHERE ingestion_run_id=identifier)
                OR EXISTS(SELECT 1 FROM historical_activity_coverage
                    WHERE ingestion_run_id=identifier) THEN
                RAISE EXCEPTION 'Pinned historical activity proof is immutable' USING ERRCODE='23514';
            END IF;
            RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
        END $$;
        CREATE TRIGGER historical_activity_proof BEFORE INSERT ON historical_activity_coverage
            FOR EACH ROW EXECUTE FUNCTION historical_activity_proof_guard();
        CREATE TRIGGER historical_activity_proof BEFORE UPDATE OR DELETE ON ingestion_runs
            FOR EACH ROW EXECUTE FUNCTION historical_activity_proof_guard();
        CREATE TRIGGER historical_activity_proof BEFORE INSERT OR UPDATE OR DELETE
            ON source_record_occurrences FOR EACH ROW EXECUTE FUNCTION historical_activity_proof_guard();
    """)


def _remove_activity_proofs() -> None:
    op.execute("DROP TRIGGER historical_activity_proof ON historical_activity_coverage")
    op.execute("DROP TRIGGER historical_activity_proof ON ingestion_runs")
    op.execute("DROP TRIGGER historical_activity_proof ON source_record_occurrences")
    op.execute("DROP FUNCTION historical_activity_proof_guard()")
